typedef struct { const char *route; int outq; } rule_t;
static const rule_t RULES[] = { {"order.created", PAY_QID}, {"order.shipped", FUL_QID} };

for (;;) {
    struct msgbuf buf;                                  /* mtype + payload */
    ssize_t n = msgrcv(IN_QID, &buf, sizeof buf.mtext, 0, 0);
    if (n < 0) { if (errno == EINTR) continue; break; }
    int outq = route_for(buf.mtext, (size_t)n, RULES, sizeof RULES / sizeof *RULES);
    if (outq < 0 || msgsnd(outq, &buf, (size_t)n, 0) < 0)   /* unmodified */
        msgsnd(DEAD_QID, &buf, (size_t)n, IPC_NOWAIT);      /* never drop */
}
